import{_ as t,o as a,c as r,am as i}from"./chunks/framework.BCmjHDVz.js";const u=JSON.parse('{"title":"Performance benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"manual/benchmarks.md","filePath":"manual/benchmarks.md","lastUpdated":null}'),s={name:"manual/benchmarks.md"};function o(l,e,n,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="Performance-benchmarks" tabindex="-1">Performance benchmarks <a class="header-anchor" href="#Performance-benchmarks" aria-label="Permalink to &quot;Performance benchmarks {#Performance-benchmarks}&quot;">​</a></h1><p>Copulas.jl uses two complementary benchmark systems.</p><h2 id="Performance-over-time" tabindex="-1">Performance over time <a class="header-anchor" href="#Performance-over-time" aria-label="Permalink to &quot;Performance over time {#Performance-over-time}&quot;">​</a></h2><p><a href="https://github.com/KristofferC/Tachometer.jl" target="_blank" rel="noreferrer">Tachometer</a> runs the native Julia suite on pull requests, compares changes with their merge base, and records default-branch results. Its dashboard is published alongside this documentation at <a href="https://lrnv.github.io/Copulas.jl/benchmarks/" target="_blank" rel="noreferrer">the Copulas.jl benchmark dashboard</a>.</p><h2 id="Comparison-with-R" tabindex="-1">Comparison with R <a class="header-anchor" href="#Comparison-with-R" aria-label="Permalink to &quot;Comparison with R {#Comparison-with-R}&quot;">​</a></h2><p>The documentation build compares Copulas.jl with R&#39;s <a href="https://cran.r-project.org/package=copula" target="_blank" rel="noreferrer"><code>copula</code></a> package. The initial set covers a few representative operations rather than every family and dimension:</p><ul><li><p>Clayton and Gaussian sampling;</p></li><li><p>Gumbel log-density evaluation;</p></li><li><p>pseudo-observations;</p></li><li><p>Gumbel inverse-Kendall fitting.</p></li></ul><p>The Julia documentation process measures the Julia operations directly and invokes one <code>Rscript</code> process for their R equivalents. Both languages are warmed up before five batched timing samples are collected. Package loading, Julia compilation, and R process startup are excluded. The resulting table is inserted immediately before Documenter builds the site, so every preview and release page shows numbers measured by its own workflow run.</p><p>&lt;!– BEGIN JULIA_VS_R_RESULTS –&gt;</p><h3 id="Results-from-this-documentation-build" tabindex="-1">Results from this documentation build <a class="header-anchor" href="#Results-from-this-documentation-build" aria-label="Permalink to &quot;Results from this documentation build {#Results-from-this-documentation-build}&quot;">​</a></h3><p>Generated at <code>2026-08-11T13:08:47Z</code> from <a href="https://github.com/lrnv/Copulas.jl/commit/ed7d1dec457673d89a356ffec1889a2b1fc5ecb7" target="_blank" rel="noreferrer"><code>ed7d1dec</code></a>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Target</th><th style="text-align:right;">Julia median</th><th style="text-align:right;">R median</th><th style="text-align:right;">R / Julia</th></tr></thead><tbody><tr><td style="text-align:right;">Clayton sampling (<code>d=5</code>, <code>n=10,000</code>)</td><td style="text-align:right;">7.39 ms</td><td style="text-align:right;">3.60 ms</td><td style="text-align:right;">0.49×</td></tr><tr><td style="text-align:right;">Gaussian sampling (<code>d=10</code>, <code>n=10,000</code>)</td><td style="text-align:right;">2.16 ms</td><td style="text-align:right;">10.00 ms</td><td style="text-align:right;">4.62×</td></tr><tr><td style="text-align:right;">Gumbel log-density (<code>d=5</code>, <code>n=10,000</code>)</td><td style="text-align:right;">9.26 ms</td><td style="text-align:right;">76.70 ms</td><td style="text-align:right;">8.28×</td></tr><tr><td style="text-align:right;">Pseudo-observations (<code>d=5</code>, <code>n=10,000</code>)</td><td style="text-align:right;">3.00 ms</td><td style="text-align:right;">7.80 ms</td><td style="text-align:right;">2.60×</td></tr><tr><td style="text-align:right;">Gumbel inverse-Kendall fit (<code>n=2,000</code>)</td><td style="text-align:right;">170.74 μs</td><td style="text-align:right;">1.20 ms</td><td style="text-align:right;">7.03×</td></tr></tbody></table><p>Five samples of ten evaluations; median steady-state time per evaluation. Runner: <code>Linux</code> / <code>x86_64</code>. Julia 1.12.6 with Copulas.jl 0.1.39; R version 4.6.1 (2026-06-24) with copula 1.1.7.</p><p>&lt;!– END JULIA_VS_R_RESULTS –&gt;</p><div class="tip custom-block"><div class="custom-block-title">Tip: Interpreting results</div><div class="custom-block-content"><p>These are lightweight, indicative measurements from shared GitHub-hosted runners, not a controlled benchmarking study. Small differences should not be interpreted as universal performance claims.</p></div></div>',15)])])}const p=t(s,[["render",o]]);export{u as __pageData,p as default};
